class Solution:
    def getEncryptedString(self, s, k):
        n = len(s)
        return ''.join(s[(i + k) % n] for i in range(n))

c.cpp:
class Solution {
public:
    string getEncryptedString(string s, int k) {
        int n = s.size();
        string res = s;
        for (int i = 0; i < n; i++) res[i] = s[(i + k) % n];
        return res;
    }
};

c.java:
class Solution {
    public String getEncryptedString(String s, int k) {
        int n = s.length();
        char[] res = new char[n];
        for (int i = 0; i < n; i++) res[i] = s.charAt((i + k) % n);
        return new String(res);
    }
}

